private int[] findEquivalent(int[] arr) {
  int[] equiv = new int[arr.length];
  for (int i = 0; i < arr.length; i++) {
    equiv[i] = i;
  }
  boolean found = false;
  while (!found) {
    found = true;
    for (int i = 0; i < arr.length; i++) {
      if (i % 2 == 0 && arr[i] == arr[i + 1]) {
        equiv[i] = equiv[i + 1];
        found = false;
      } else if (i % 2 == 1 && arr[i] == arr[i - 1]) {
        equiv[i] = equiv[i - 1];
        found = false;
      }
    }
  }
  return equiv;
}

