public class SteppingNumbers {

    public static List<Integer> findSteppingNumbers(int low, int high) {
        List<Integer> steppingNumbers = new ArrayList<>();
        String lowString = low + "";
        String highString = high + "";
        for (int i = low; i < high; i++) {
            String currentString = i + "";
            boolean isSteppingNumber = true;
            for (int j = 0; j < currentString.length(); j++) {
                if (currentString.charAt(j) == '9') {
                    isSteppingNumber = false;
                    break;
                }
                int adjacentDigit = Integer.parseInt(currentString.charAt(j + 1) + "");
                int currentDigit = Integer.parseInt(currentString.charAt(j) + "");
                if (currentDigit - adjacentDigit != 1 && currentDigit - adjacentDigit != -1) {
                    isSteppingNumber = false;
                    break;
                }
            }
            if (isSteppingNumber) {
                steppingNumbers.add(i);
            }
        }
        return steppingNumbers;
    }

    public static void main(String[] args) {
        List<Integer> steppingNumbers = findSteppingNumbers(0, 21);
        for (int steppingNumber : steppingNumbers) {
            System.out.println(steppingNumber);
        }
    }
}

public static int countDigitOne(int n) {
    int count = 0;
    for (int i = 1; i <= n; i++) {
        while (i > 0) {
            if (i % 10 == 1) {
                count++;
            }
            i /= 10;
        }
    }
    return count;
}

