public static int longestLine(int[][] mat) {
    int m = mat.length;
    int n = mat[0].length;
    int maxLength = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                int currentLength = 0;
                for (int k = i; k < m && k < i + maxLength; k++) {
                    if (mat[k][j] == 0) {
                        break;
                    }
                    currentLength++;
                }
                for (int k = j; k < n && k < j + maxLength; k++) {
                    if (mat[i][k] == 0) {
                        break;
                    }
                    currentLength++;
                }
                maxLength = Math.max(maxLength, currentLength);
            }
        }
    }

    return maxLength;
}
