public static int squarePermutations(int[] A) {
    int[] list = Arrays.copyOf(A, A.length);
    Arrays.sort(list);
    int[] dp = new int[list.length];
    dp[list.length - 1] = 1;
    for (int i = list.length - 2; i >= 0; i--) {
        int sum = 0;
        for (int j = i + 1; j < list.length && sum < list[i]; j++) {
            sum += list[j];
        }
        dp[i] = sum * dp[i + 1];
    }
    return dp[0];
}
