public static int largestRectangleArea(int[] heights) {
    int maxArea = 0;
    int currentArea = 0;
    int i = 0;
    while (i < heights.length) {
        int height = heights[i];
        int j = i;
        while (j < heights.length && heights[j] >= height) {
            j++;
        }
        currentArea = height * (j - i);
        maxArea = Math.max(maxArea, currentArea);
        i = j;
    }
    return maxArea;
}

