    int numCols = mat[0].length;
    int[] result = new int[numRows + numCols - 1];
    int index = 0;

    for (int i = 0; i < numRows && i < numCols; i++) {
        result[index++] = mat[i][i];
    }

    for (int i = 1; i < numRows && i < numCols - 1; i++) {
        result[index++] = mat[i][numCols - i - 1];
    }

    if (numRows > 1 && numRows > numCols) {
        result[index++] = mat[numRows - 1][numCols - 1];
    }

    return result;
}
