public static int calculateEnergy(String s) {
    int longest = 0;
    for (int i = 0, j = 0; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(j)) {
            longest = Math.max(longest, i - j + 1);
        } else {
            j = i + 1;
        }
    }
    return longest;
}

