public static int calculateUniqueSum(int[] nums) {
    Set<Integer> uniqueElements = new HashSet<>();
    int sum = 0;
    for (int i = 0; i < nums.length; i++) {
        if (!uniqueElements.contains(nums[i])) {
            uniqueElements.add(nums[i]);
            sum += nums[i];
        }
    }
    return sum;
}
